INSERT INTO jump1_products (id, name, category, category_id, global_order, category_order, price, description, full_description, material, specifications, images, project, created_at, updated_at)
VALUES
  ('GEM1', 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Sunshine (เจิดจรัสดั่งแสงทองของวันใหม่)', 'ring', NULL, 1, 1, NULL, 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Sunshine (เจิดจรัสดั่งแสงทองของวันใหม่)', 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Sunshine (เจิดจรัสดั่งแสงทองของวันใหม่)\n\nพระอาทิตย์ สัญลักษณ์แห่งการเริ่มต้นวันใหม่ มีแสงสว่างนำทางชีวิต ให้ชีวิตพ้นความมืดมิด เป็นการชี้ทางสว่าง การเริ่มโอกาสใหม่ๆ \nผสมผสานกับ พลอยนพเก้าแท้ตรงตามตำรา เกรด Premium \nที่ถูกคัดสรรก้อนพลอยชั้นเลิศ และ เจียระไนจากช่างฝีมือชั้นครู \n\nการดีไซน์ เลือกพลอยบุษราคัมน้ำทองแท้ธรรมชาติ เจียระไนเหลี่ยมเพชร เกรด Premium ไว้ตรงกลาง ล้อมรอบด้วยพลอยนพเก้าแท้ตรงตามตำราทุกประการเกรด Premium อีก 8 ชนิด อย่างลงตัว โดดเด่น ช่วยเติมพลังบวกและนำพาสิ่งดีๆ ให้กับผู้สวมใส่\n\nขนาดเส้นผ่าศูนย์กลางประมาณ 15 mm\n\nใช้พลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium \n▪ พลอยไพลินแท้ \n▪ พลอยทับทิมแท้ \n▪ พลอยบุษราคัมแท้ \n▪ พลอยมรกตแท้ \n▪ พลอยเพทายแท้ \n▪ พลอยมุกดาหารแท้ \n▪ พลอยโกเมนแท้ \n▪ พลอยตาแมวแท้ \n▪ เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS VS', 'พลอยไพลินแท้, พลอยทับทิมแท้, พลอยบุษราคัมแท้, พลอยมรกตแท้, พลอยเพทายแท้, พลอยมุกดาหารแท้, พลอยโกเมนแท้, พลอยตาแมวแท้, เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS VS', '{"size":"ขนาดเส้นผ่าศูนย์กลางประมาณ 15 mm"}', '["/Product/GEM1/S__18235446_0_0.jpg","/Product/GEM1/S__18235448_0_0.jpg","/Product/GEM1/S__18235449_0_0.jpg","/Product/GEM1/S__18235450_0_0.jpg","/Product/GEM1/S__18235451_0_0.jpg","/Product/GEM1/S__18235452_0_0.jpg","/Product/GEM1/S__18235453_0_0.jpg","/Product/GEM1/S__18235454_0_0.jpg","/Product/GEM1/S__18235455_0_0.jpg","/Product/GEM1/S__18235456_0_0.jpg","/Product/GEM1/S__18235457_0_0.jpg","/Product/GEM1/S__18235459_0_0.jpg","/Product/GEM1/S__18456711_0_0.jpg","/Product/GEM1/S__18456714_0_0.jpg","/Product/GEM1/S__18456715_0_0.jpg","/Product/GEM1/S__18456720_0_0.jpg","/Product/GEM1/S__18456722_0_0.jpg","/Product/GEM1/S__18456725_0_0.jpg","/Product/GEM1/S__18456728_0_0.jpg","/Product/GEM1/S__18456764_0_0.jpg","/Product/GEM1/S__18456766_0_0.jpg","/Product/GEM1/S__18456767_0_0.jpg","/Product/GEM1/S__18456768_0_0.jpg"]', 'jump1', '2026-06-15T17:29:44.346Z', '2026-06-15T17:29:44.346Z'),
  ('gem2', 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Beehive', 'ring', NULL, 2, 2, NULL, 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Beehive', 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Beehive\n\nได้รับแรงบันดาลใจมาจากรังผึ้ง ที่เป็นสัญลักษณ์ของความมั่งคั่ง อุดมสมบูรณ์ ช่วยในเรื่องของสุขภาพที่ดี การเงิน และความร่ำรวย \nผึ้งเป็นแมลงนำโชคที่ขยันทำงาน สร้างรังผึ้งจนใหญ่โต มีบริวารผึ้งมากมายอยู่กันอย่างดีมีสุข ให้ผลผลิตคือน้ำผึ้ง ที่มีค่าและหายาก\nผสมผสานกับ พลอยนพเก้าแท้ตรงตามตำรา เกรด Premium \nที่ถูกคัดสรรก้อนพลอยชั้นเลิศ และ เจียระไนจากช่างฝีมือชั้นครู \n\nหน้าแหวนกว้าง 8.7 mm\n\nใช้พลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium \n▪ พลอยไพลินแท้ \n▪ พลอยทับทิมแท้ \n▪ พลอยบุษราคัมแท้ \n▪ พลอยมรกตแท้ \n▪ พลอยเพทายแท้ \n▪ พลอยมุกดาหารแท้ \n▪ พลอยโกเมนแท้ \n▪ พลอยตาแมวแท้ \n▪ เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS VS', 'พลอยไพลินแท้, พลอยทับทิมแท้, พลอยบุษราคัมแท้, พลอยมรกตแท้, พลอยเพทายแท้, พลอยมุกดาหารแท้, พลอยโกเมนแท้, พลอยตาแมวแท้, เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS VS', '{"size":"หน้าแหวนกว้าง 8.7 mm"}', '["/Product/gem2/S__18235446_0_0.jpg","/Product/gem2/S__18235448_0_0.jpg","/Product/gem2/S__18235449_0_0.jpg","/Product/gem2/S__18235450_0_0.jpg","/Product/gem2/S__18235451_0_0.jpg","/Product/gem2/S__18235452_0_0.jpg","/Product/gem2/S__18235453_0_0.jpg","/Product/gem2/S__18235454_0_0.jpg","/Product/gem2/S__18235455_0_0.jpg","/Product/gem2/S__18235456_0_0.jpg","/Product/gem2/S__18235457_0_0.jpg","/Product/gem2/S__18235459_0_0.jpg","/Product/gem2/S__18456711_0_0.jpg","/Product/gem2/S__18456714_0_0.jpg","/Product/gem2/S__18456715_0_0.jpg","/Product/gem2/S__18456720_0_0.jpg","/Product/gem2/S__18456722_0_0.jpg","/Product/gem2/S__18456725_0_0.jpg","/Product/gem2/S__18456728_0_0.jpg","/Product/gem2/S__18456764_0_0.jpg","/Product/gem2/S__18456766_0_0.jpg","/Product/gem2/S__18456767_0_0.jpg","/Product/gem2/S__18456768_0_0.jpg"]', 'jump1', '2026-06-15T17:29:44.431Z', '2026-06-15T17:29:44.431Z'),
  ('gem3', 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Chess', 'ring', NULL, 3, 3, NULL, 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Chess', 'แหวนนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Chess\n	\nได้รับแรงบันดาลใจจาก หมากรุก สัญลักษณ์แห่งปัญญา ความเฉลียวฉลาด มีสตินำทางชีวิต เป็นการชี้ทางสว่าง \n\nการดีไซน์ เลือกใช้พลอยนพเก้าแท้ตรงตามตำราเกรด Premium รูปทรงสี่เหลี่ยม จากโรงงานของ Niwelry รังสรรค์เหมือนตารางหมากรุก สวยงาม หรูหรามีเอกลักษณ์ สะท้อนตัวตนอันเจิดจรัสช่วยเติมพลังบวกและนำพาสิ่งดีๆ ให้กับผู้สวมใส่\n\nหน้าแหวนกว้างประมาณ 5.5 mm\n\nใช้พลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium \n▪ พลอยไพลินแท้ \n▪ พลอยทับทิมแท้ \n▪ พลอยบุษราคัมแท้ \n▪ พลอยมรกตแท้ \n▪ พลอยเพทายแท้ \n▪ พลอยมุกดาหารแท้ \n▪ พลอยโกเมนแท้ \n▪ พลอยตาแมวแท้ \n▪ เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS VS', 'พลอยไพลินแท้, พลอยทับทิมแท้, พลอยบุษราคัมแท้, พลอยมรกตแท้, พลอยเพทายแท้, พลอยมุกดาหารแท้, พลอยโกเมนแท้, พลอยตาแมวแท้, เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS VS', '{"size":"หน้าแหวนกว้างประมาณ 5.5 mm"}', '["/Product/gem3/S__18366469_0_0.jpg","/Product/gem3/S__18366471_0_0.jpg","/Product/gem3/S__18587754_0_0.jpg","/Product/gem3/S__18587755_0_0.jpg","/Product/gem3/S__18587756_0_0.jpg","/Product/gem3/S__18587758_0_0.jpg","/Product/gem3/S__18587759_0_0.jpg","/Product/gem3/S__19251276_0.jpg","/Product/gem3/S__19251277_0.jpg"]', 'jump1', '2026-06-15T17:29:44.516Z', '2026-06-15T17:29:44.516Z'),
  ('Gem4', 'ต่างหูนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Renita', 'earring', NULL, 4, 1, NULL, 'ต่างหูนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Renita', 'ต่างหูนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Renita\n\nความเชื่อ ความศรัทธาของพลอยนพเก้า หรือ อัญมณีมงคล ๙ ชนิด ตามตำราโหราศาสตร์ไทยโบราณ ที่ช่วยปรับพื้นดวงให้สมดุล ช่วยเสริมโชคลาภ ความโชคดีในด้านต่างๆ ทั้งเรื่องการเงิน การงาน ความรัก สุขภาพ บารมีและความสำเร็จ\n\nได้รับแรงบันดาลใจจากความสง่างาม (Renita) ดีไซน์ หรูหรา ทันสมัย ใส่ออกงานก็ได้ ใส่ในชีวิตประจำวันก็ดูดี เลือกพลอยนพเก้าแท้ตรงตามตำรา เจียระไนเหลี่ยมเพชร เกรด Premium หลากหลายรูปทรง จากโรงงานของ Niwelry โดยเฉพาะ\nเปล่งประกายระยิบระยับ โดดเด่น สง่างาม มีเอกลักษณ์อย่างลงตัว ช่วยเติมพลังบวก เสริมความมั่นใจ นำพาความสุขและสิ่งดีๆ ให้กับผู้สวมใส่\n\nพลอยนพเก้าแท้ตรงตามตำรา เกรด Premium \nที่ถูกคัดสรรก้อนพลอยดิบชั้นเลิศ ระดับโลก ถูกเจียระไนจากช่างฝีมือชั้นครูที่มีประสบการณ์ยาวนานกว่า 40 ปี \n\nNiwelry เป็นโรงงานอัญมณีแท้ธรรมชาติ เราไม่ใช้พลอยชนิดใดๆ แทนพลอยนพเก้าตรงตามตำราโบราณ \nพลอยทุกชนิดเป็นพลอยนพเก้าแท้ตามตำราแน่นอน 100% (สามารถออกใบ Certificate จาก Lab ได้ คิดค่าใช้จ่ายตามจริงค่ะ)\n\nเครื่องประดับทองแท้ มีให้เลือก 18k 14k 9k (Yellow Gold, White Gold หรือ Pink Gold)\n\nขนาดเส้นผ่าศูนย์กลางประมาณ  6.95 x 7.18 mm \n\nพลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium\n▪ พลอยไพลินแท้ (Natural Blue Sapphire)\n▪ พลอยทับทิมแท้ (Natural Ruby)\n▪ พลอยบุษราคัมแท้ (Natural Yellow Sapphire)\n▪ พลอยมรกตแท้ (Natural Emerald)\n▪ พลอยเพทายแท้ (Natural Zircon)\n▪ พลอยมุกดาหารแท้ (Natural Moonstone)\n▪ พลอยโกเมนแท้ (Natural Garnet)\n▪ พลอยตาแมวแท้ (Natural Cat eye)\n▪ เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS (Natural Diamond)', 'พลอยไพลินแท้ (Natural Blue Sapphire), พลอยทับทิมแท้ (Natural Ruby), พลอยบุษราคัมแท้ (Natural Yellow Sapphire), พลอยมรกตแท้ (Natural Emerald), พลอยเพทายแท้ (Natural Zircon), พลอยมุกดาหารแท้ (Natural Moonstone), พลอยโกเมนแท้ (Natural Garnet), พลอยตาแมวแท้ (Natural Cat eye), เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS (Natural Diamond)', '{"size":"ขนาดเส้นผ่าศูนย์กลางประมาณ  6.95 x 7.18 mm"}', '["/Product/Gem4/LINE_ALBUM_4625_250424_1_0.jpg","/Product/Gem4/S__12320851_0_0.jpg","/Product/Gem4/S__12320853_0_0.jpg","/Product/Gem4/S__12320854_0_0.jpg","/Product/Gem4/S__12320855_0_0.jpg","/Product/Gem4/S__12320856_0_0.jpg","/Product/Gem4/S__12320857_0_0.jpg","/Product/Gem4/S__12320858_0_0.jpg","/Product/Gem4/S__12320860_0_0.jpg","/Product/Gem4/S__19865728_0_0.jpg"]', 'jump1', '2026-06-15T17:29:44.592Z', '2026-06-15T17:29:44.592Z'),
  ('Gem5', 'ต่างหูนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Tara', 'earring', NULL, 5, 2, NULL, 'ต่างหูนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Tara', 'ต่างหูนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Tara\n\nความเชื่อ ความศรัทธาของพลอยนพเก้า หรือ อัญมณีมงคล ๙ ชนิด ตามตำราโหราศาสตร์ไทยโบราณ ที่ช่วยปรับพื้นดวงให้สมดุล ช่วยเสริมโชคลาภ ความโชคดีในด้านต่างๆ ทั้งเรื่องการเงิน การงาน ความรัก สุขภาพ บารมีและความสำเร็จ\n\nได้รับแรงบันดาลใจจากดวงดาว (Tara) ที่เจิดจรัส เปล่งประกายระยิบระยับ บนท้องฟ้า เหมือนพลอยนพเก้าแท้ตรงตามตำรา เจียระไนทรงกลมเหลี่ยมเพชร เกรด Premium จากโรงงานของ Niwelry โดยเฉพาะ\nด้วยดีไซส์โดดเด่น มีเอกลักษณ์ ช่วยเติมพลังบวก เสริมความมั่นใจ นำพาความสุขและสิ่งดีๆ ให้กับผู้สวมใส่\n\nพลอยนพเก้าแท้ตรงตามตำรา เกรด Premium \nที่ถูกคัดสรรก้อนพลอยดิบชั้นเลิศ ระดับโลก ถูกเจียระไนจากช่างฝีมือชั้นครูที่มีประสบการณ์ยาวนานกว่า 40 ปี \n\nNiwelry เป็นโรงงานอัญมณีแท้ธรรมชาติ เราไม่ใช้พลอยชนิดใดๆ แทนพลอยนพเก้าตรงตามตำราโบราณ \nพลอยทุกชนิดเป็นพลอยนพเก้าแท้ตามตำราแน่นอน 100% (สามารถออกใบ Certificate จาก Lab ได้ คิดค่าใช้จ่ายตามจริงค่ะ)\n\nเครื่องประดับทองแท้ มีให้เลือก 18k 14k 9k (Yellow Gold, White Gold หรือ Pink Gold)\n\nขนาดเส้นผ่าศูนย์กลางประมาณ  7.0 x 5.5 mm \n\nพลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium\n▪ พลอยไพลินแท้ (Natural Blue Sapphire)\n▪ พลอยทับทิมแท้ (Natural Ruby)\n▪ พลอยบุษราคัมแท้ (Natural Yellow Sapphire)\n▪ พลอยมรกตแท้ (Natural Emerald)\n▪ พลอยเพทายแท้ (Natural Zircon)\n▪ พลอยมุกดาหารแท้ (Natural Moonstone)\n▪ พลอยโกเมนแท้ (Natural Garnet)\n▪ พลอยตาแมวแท้ (Natural Cat eye)\n▪ เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS (Natural Diamond)', 'พลอยไพลินแท้ (Natural Blue Sapphire), พลอยทับทิมแท้ (Natural Ruby), พลอยบุษราคัมแท้ (Natural Yellow Sapphire), พลอยมรกตแท้ (Natural Emerald), พลอยเพทายแท้ (Natural Zircon), พลอยมุกดาหารแท้ (Natural Moonstone), พลอยโกเมนแท้ (Natural Garnet), พลอยตาแมวแท้ (Natural Cat eye), เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS (Natural Diamond)', '{"size":"ขนาดเส้นผ่าศูนย์กลางประมาณ  7.0 x 5.5 mm"}', '["/Product/Gem5/LINE_ALBUM_4625_250424_2_0.jpg","/Product/Gem5/S__14172267_0.jpg","/Product/Gem5/S__14172270_0.jpg","/Product/Gem5/S__14172273_0.jpg","/Product/Gem5/S__19906573_0_0.jpg","/Product/Gem5/S__19906574_0_0.jpg","/Product/Gem5/S__19906575_0_0.jpg","/Product/Gem5/S__19906576_0_0.jpg","/Product/Gem5/S__19922953_0.jpg","/Product/Gem5/S__21684232_0.jpg"]', 'jump1', '2026-06-15T17:29:44.691Z', '2026-06-15T17:29:44.691Z'),
  ('Gem6', 'แหวนพลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Nine Princess Gems', 'ring', NULL, 6, 4, NULL, 'แหวนพลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Nine Princess Gems', 'แหวนพลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium รุ่น Nine Princess Gems\n \nความเชื่อ ความศรัทธาของพลอยนพเก้า หรือ อัญมณีมงคล ๙ ชนิด ตามตำราโหราศาสตร์ไทยโบราณ ที่ช่วยปรับพื้นดวงให้สมดุล ช่วยเสริมโชคลาภ ความโชคดีในด้านต่างๆ ทั้งเรื่องการเงิน การงาน ความรัก สุขภาพ บารมีและความสำเร็จ\n\nดีไซน์เรียบหรู สวยงามและทรงคุณค่า\nพลอยนพเก้าแท้ธรรมชาติตรงตามตำราทุกประการ เจียระไนรูปทรงสี่เหลี่ยม เกรด Premium ที่ถูกคัดสรรก้อนพลอยชั้นเลิศ ถูกเจียระไนจากช่างฝีมือชั้นครู จากโรงงานของ Niwelry โดยเฉพาะ ผสมผสานเพชรแท้ธรรมชาติเบลเยี่ยมคัท อย่างลงตัว มีเอกลักษณ์เฉพาะตัว สีสันสดใส โดดเด่น ช่วยเติมพลังบวก เสริมความมั่นใจ นำพาความสุขและสิ่งดีๆ ให้กับผู้สวมใส่\n\nพลอยนพเก้าแท้ตรงตามตำรา เกรด Premium \nที่ถูกคัดสรรก้อนพลอยดิบชั้นเลิศ ระดับโลก ถูกเจียระไนจากช่างฝีมือชั้นครูที่มีประสบการณ์ยาวนานกว่า 40 ปี \n\nNiwelry เป็นโรงงานอัญมณีแท้ธรรมชาติ เราไม่ใช้พลอยชนิดใดๆ แทนพลอยนพเก้าตรงตามตำราโบราณ \nพลอยทุกชนิดเป็นพลอยนพเก้าแท้ตามตำราแน่นอน 100% (สามารถออกใบ Certificate จาก Lab ได้ คิดค่าใช้จ่ายตามจริงค่ะ)\n\nเครื่องประดับทองแท้ มีให้เลือก 18k 14k 9k (Yellow Gold, White Gold หรือ Pink Gold)\n\nขนาดเส้นผ่าศูนย์กลางประมาณ  4 mm \n\nพลอยนพเก้าแท้ตรงตามตำราทุกประการ เกรด Premium\n▪ พลอยไพลินแท้ (Natural Blue Sapphire)\n▪ พลอยทับทิมแท้ (Natural Ruby)\n▪ พลอยบุษราคัมแท้ (Natural Yellow Sapphire)\n▪ พลอยมรกตแท้ (Natural Emerald)\n▪ พลอยเพทายแท้ (Natural Zircon)\n▪ พลอยมุกดาหารแท้ (Natural Moonstone)\n▪ พลอยโกเมนแท้ (Natural Garnet)\n▪ พลอยตาแมวแท้ (Natural Cat eye)\n▪ เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS (Natural Diamond)', 'พลอยไพลินแท้ (Natural Blue Sapphire), พลอยทับทิมแท้ (Natural Ruby), พลอยบุษราคัมแท้ (Natural Yellow Sapphire), พลอยมรกตแท้ (Natural Emerald), พลอยเพทายแท้ (Natural Zircon), พลอยมุกดาหารแท้ (Natural Moonstone), พลอยโกเมนแท้ (Natural Garnet), พลอยตาแมวแท้ (Natural Cat eye), เพชรแท้ธรรมชาติ เบลเยี่ยมคัท น้ำ 100-98 VVS (Natural Diamond)', '{"size":"ขนาดเส้นผ่าศูนย์กลางประมาณ  4 mm"}', '["/Product/Gem6/S__15401064_0_0.jpg","/Product/Gem6/S__15401066_0_0.jpg","/Product/Gem6/S__15401068_0_0.jpg","/Product/Gem6/S__15401069_0_0.jpg","/Product/Gem6/S__15401140_0_0.jpg","/Product/Gem6/S__15466591_0.jpg","/Product/Gem6/S__20390009_0_0.jpg"]', 'jump1', '2026-06-15T17:29:44.784Z', '2026-06-15T17:29:44.784Z') ON CONFLICT (id) DO NOTHING;
